args.sparql:
PREFIX dbo: <http://dbpedia.org/ontology/>
PREFIX dbp: <http://dbpedia.org/property/>
PREFIX dbr: <http://dbpedia.org/resource/>
SELECT ?person ?prop ?date WHERE {
  VALUES ?person { dbr:Geoff_Bagnall dbr:Caroline_Huppert }
  { ?person dbo:birthDate ?date . BIND(dbo:birthDate AS ?prop) }
  UNION
  { ?person dbp:birthDate ?date . BIND(dbp:birthDate AS ?prop) }
} ORDER BY ?person ?prop

PREFIX dbo: <http://dbpedia.org/ontology/>
PREFIX dbp: <http://dbpedia.org/property/>
PREFIX dbr: <http://dbpedia.org/resource/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
SELECT ?earlier ?earlierLabel ?earlierBirthDate ?later ?laterLabel ?laterBirthDate WHERE {
  BIND(dbr:Geoff_Bagnall AS ?p1)
  BIND(dbr:Caroline_Huppert AS ?p2)

  OPTIONAL { ?p1 dbo:birthDate ?p1_dbo. }
  OPTIONAL { ?p1 dbp:birthDate ?p1_dbp. }
  OPTIONAL { ?p2 dbo:birthDate ?p2_dbo. }
  OPTIONAL { ?p2 dbp:birthDate ?p2_dbp. }

  BIND(COALESCE(?p1_dbo, ?p1_dbp) AS ?bd1)
  BIND(COALESCE(?p2_dbo, ?p2_dbp) AS ?bd2)

  FILTER(bound(?bd1) && bound(?bd2))

  BIND(IF(?bd1 < ?bd2, ?p1, ?p2) AS ?earlier)
  BIND(IF(?bd1 < ?bd2, ?bd1, ?bd2) AS ?earlierBirthDate)
  BIND(IF(?bd1 < ?bd2, ?p2, ?p1) AS ?later)
  BIND(IF(?bd1 < ?bd2, ?bd2, ?bd1) AS ?laterBirthDate)

  OPTIONAL { ?earlier rdfs:label ?earlierLabel FILTER(lang(?earlierLabel)='en') }
  OPTIONAL { ?later rdfs:label ?laterLabel FILTER(lang(?laterLabel)='en') }
}

