  BIND(COALESCE(?p2_dbo , ?p2_dbp) AS ?bd2)
  FILTER(bound(?bd1) && bound(?bd2))
  BIND(IF(?bd1 < ?bd2 , ?p1 , ?p2) AS ?earlier)
